package io.karpfen.features.runtime

import io.karpfen.features.ComplexStateMachineBenchmark
import io.karpfen.io.karpfen.features.runtime.event.EventInjectionFeature
import io.karpfen.io.karpfen.features.runtime.event.EventRecordingFeature
import io.karpfen.io.karpfen.features.runtime.event.EventReplayControllerFeature
import kotlinx.benchmark.Benchmark
import kotlinx.benchmark.Setup
import kotlinx.benchmark.TearDown

class EventReplayOverhead: ComplexStateMachineBenchmark() {

    @Setup
    fun featureActivation() {
        this.featureManager.requestFeatureActivation(EventReplayControllerFeature::class)
    }

    @TearDown
    fun featureDeactivation() {
        this.featureManager.requestFeatureDeactivation(EventReplayControllerFeature::class)
    }

    @Benchmark
    fun idle() {
        this.startBenchmark()
    }
}

class EventReplayRecordingOverhead: ComplexStateMachineBenchmark() {

    @Setup
    fun featureActivation() {
        this.featureManager.requestFeatureActivation(EventReplayControllerFeature::class)
        this.featureManager.onMessage(EventRecordingFeature::class, "start")
    }

    @TearDown
    fun featureDeactivation() {
        this.featureManager.onMessage(EventRecordingFeature::class, "stop")
        this.featureManager.requestFeatureDeactivation(EventReplayControllerFeature::class)
    }

    @Benchmark
    fun record() {
        this.startBenchmark()
    }
}

