    @Setup
    fun featureActivation() {
        this.featureManager.requestFeatureActivation(EventReplayControllerFeature::class)
        this.featureManager.onMessage(EventInjectionFeature::class, "start")
    }

    //upload events before every iteration
    override fun setup() {
        super.setup()
        this.featureManager.onMessage(EventInjectionFeature::class, "upload:$events")
    }

    @TearDown
    fun featureDeactivation() {
        this.featureManager.onMessage(EventInjectionFeature::class, "stop")
        this.featureManager.requestFeatureDeactivation(EventReplayControllerFeature::class)
    }

    //Bypass normal event injection
    @Benchmark
    fun inject() {
        this.engine.runLoop(contexts, mutableMapOf()) {}
    }
